import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BEmfQga0.js";const m=JSON.parse('{"title":"Adding a New Host","description":"","frontmatter":{},"headers":[],"relativePath":"host-adapter-development/adding-new-host.md","filePath":"host-adapter-development/adding-new-host.md","lastUpdated":1788258471000}'),n={name:"host-adapter-development/adding-new-host.md"};function i(s,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="adding-a-new-host" tabindex="-1">Adding a New Host <a class="header-anchor" href="#adding-a-new-host" aria-label="Permalink to &quot;Adding a New Host&quot;">​</a></h1><p>This page consolidates the checklists from the <a href="https://github.com/zjunlp/LightRSI/blob/main/docs/adapter-playbook.md" target="_blank" rel="noreferrer">Adapter Playbook</a> and the <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/README.md" target="_blank" rel="noreferrer">Adapters README</a>.</p><h2 id="design-first" tabindex="-1">Design First <a class="header-anchor" href="#design-first" aria-label="Permalink to &quot;Design First&quot;">​</a></h2><p>From the <a href="https://github.com/zjunlp/LightRSI/blob/main/docs/adapter-playbook.md" target="_blank" rel="noreferrer">Adapter Playbook</a>:</p><ul><li>Can the host rewrite requests before model execution?</li><li>Can the host rewrite responses after model execution?</li><li>Does the host expose streaming chunks, final responses, or both?</li><li>Does the host expose transcript history directly, or must it be reconstructed?</li><li>Is integration file-based, hook-based, plugin-based, or API-based?</li></ul><h2 id="required-surfaces" tabindex="-1">Required Surfaces <a class="header-anchor" href="#required-surfaces" aria-label="Permalink to &quot;Required Surfaces&quot;">​</a></h2><p>From the <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/README.md" target="_blank" rel="noreferrer">adapters/README.md</a> checklist:</p><ol><li><strong>Install surface</strong> — where the host extension or plugin lives, how config is written, how to enable/disable/remove.</li><li><strong>Session bridge</strong> — how session IDs, turn IDs, and workspace roots are resolved.</li><li><strong>Transcript bridge</strong> — how raw host messages are decoded into shared envelopes and rewritten envelopes encoded back.</li><li><strong>Request / response lifecycle</strong> — before-call rewriting, after-call reduction, tool-result persistence, streaming/non-streaming handling.</li><li><strong>State roots</strong> — state dir, archive dir, debug trace dir.</li><li><strong>Product surface</strong> — <code>status</code>, <code>report</code>, <code>doctor</code>, <code>visual</code>, mode switching.</li><li><strong>Verification</strong> — adapter unit tests, one smoke install path, one end-to-end session check.</li></ol><h2 id="recommended-development-order" tabindex="-1">Recommended Development Order <a class="header-anchor" href="#recommended-development-order" aria-label="Permalink to &quot;Recommended Development Order&quot;">​</a></h2><p>From the <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/README.md" target="_blank" rel="noreferrer">adapters/README.md</a>:</p><ol><li>Start with the shared host envelope bridge in <code>components/packages/foundation/host-adapter/</code>.</li><li>Wire one minimal request path through the host.</li><li>Make <code>status</code> and <code>doctor</code> work first.</li><li>Add reduction and persistence hooks.</li><li>Add visual and richer command surfaces last.</li></ol><h2 id="reference-implementations" tabindex="-1">Reference Implementations <a class="header-anchor" href="#reference-implementations" aria-label="Permalink to &quot;Reference Implementations&quot;">​</a></h2><ul><li><a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/openclaw/README.md" target="_blank" rel="noreferrer">OpenClaw Adapter</a></li><li><a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/codex/README.md" target="_blank" rel="noreferrer">Codex Adapter</a></li><li><a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/claude-code/README.md" target="_blank" rel="noreferrer">Claude Code Adapter</a></li><li><a href="https://github.com/zjunlp/LightRSI/tree/main/components/adapters/deepseek-harness" target="_blank" rel="noreferrer">DeepSeek Harness Adapter</a></li></ul><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./adapter-architecture">Adapter Architecture</a></li><li><a href="./adapter-testing">Adapter Testing</a></li><li><a href="./configuration-integration">Configuration Integration</a></li><li><a href="./hook-proxy-integration">Hook and Proxy Integration</a></li><li><a href="https://github.com/zjunlp/LightRSI/blob/main/docs/adapter-playbook.md" target="_blank" rel="noreferrer">Adapter Playbook</a></li><li><a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/HOSTS.md" target="_blank" rel="noreferrer">HOSTS.md</a></li></ul>',15)])])}const g=t(n,[["render",i]]);export{m as __pageData,g as default};
